import { useState, useCallback } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

interface ReportDatePickerProps {
  onChange?: (date: Date | null) => void;
}

function startOfDay(date: Date) {
  const d = new Date(date);
  d.setHours(0, 0, 0, 0);
  return d;
}

function addDays(date: Date, days: number) {
  const d = new Date(date);
  d.setDate(d.getDate() + days);
  return d;
}

function isSameDay(a: Date | null, b: Date) {
  if (!a) return false;
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

export default function ReportDatePicker({ onChange }: ReportDatePickerProps) {
  const [selected, setSelected] = useState<Date | null>(() => startOfDay(new Date()));

  const handleChange = useCallback(
    (date: Date | null) => {
      setSelected(date);
      onChange?.(date);
    },
    [onChange]
  );

  const today = startOfDay(new Date());
  const yesterday = addDays(today, -1);
  const weekAgo = addDays(today, -7);

  const quickOptions = [
    { label: 'Сегодня', date: today },
    { label: 'Вчера', date: yesterday },
    { label: 'Неделя назад', date: weekAgo },
  ];

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-r-sm)',
      }}
    >
      <div style={{ display: 'flex', gap: 'var(--jx-r-sm)', flexWrap: 'wrap' }}>
        {quickOptions.map((option) => (
          <JxChip
            key={option.label}
            active={isSameDay(selected, option.date)}
            onClick={() => handleChange(option.date)}
          >
            {option.label}
          </JxChip>
        ))}
      </div>
      <JxCalendar locale="ru-RU" value={selected} onValueChange={handleChange} />
    </div>
  );
}

